import React from 'react';
import { Ticket } from '../../../models/Ticket';
import { SLABadge, formatSLATime } from '../../../components/common/SLABadge';
import { StatusBadge } from '../../../components/common/StatusBadge';
import styles from './TicketHeader.module.css';

interface TicketHeaderProps {
  ticket: Ticket;
}

const TicketHeader: React.FC<TicketHeaderProps> = ({ ticket }) => {
  const getPriorityLabel = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'KHẨN CẤP';
      case 'high':
        return 'CAO';
      case 'medium':
        return 'TRUNG BÌNH';
      case 'low':
        return 'THẤP';
      default:
        return priority.toUpperCase();
    }
  };

  const getPriorityClass = (priority: string) => {
    return `priority-${priority.toLowerCase()}`;
  };

  return (
    <div className={styles.container}>
      <h1 className={styles.title}>
        Phiếu Yêu Cầu #{ticket.idCode || ticket.id.substring(0, 8).toUpperCase()}
      </h1>
      <div className={styles.badges}>
        <StatusBadge status={ticket.status} />
        <span className={`${styles.priorityBadge} ${styles[getPriorityClass(ticket.priority)]}`}>
          {getPriorityLabel(ticket.priority)}
        </span>
        <SLABadge 
          status={ticket.sla.breached ? 'breached' : ticket.sla.status === 'danger' ? 'danger' : ticket.sla.status === 'warning' ? 'warning' : 'safe'}
          timeRemaining={`SLA: ${formatSLATime(ticket.sla.remainingMinutes)}`}
        />
      </div>
    </div>
  );
};

export default TicketHeader;
