/**
 * PermissionsManagementPage
 * Admin page with two tabs:
 *   - "Quyền truy cập" — CRUD for permissions, grouped by module
 *   - "Gói tính năng"  — CRUD for feature packages + manage which permissions each package has
 */
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { adminService } from '../../services/admin';
import { useAppSelector } from '../../store/hooks';
import type {
  BffPermissionDto,
  BffFeaturePackageDto,
} from '../../services/admin/responseModel';
import { Slideout } from '../../components/common/Slideout';
import { Tabs } from '../../components/common/Tabs';
import { useResponsive } from '../../hooks/useResponsive';
import { useAppToast } from '../../hooks/useAppToast';
import styles from './PermissionsManagementPage.module.css';

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface PermissionFormData {
  code:        string;
  name:        string;
  module:      string;
  description: string;
  isActive:    boolean;
}

interface PackageFormData {
  code:        string;
  name:        string;
  description: string;
  orderIndex:  string;
  isActive:    boolean;
}

const emptyPermissionForm: PermissionFormData = {
  code: '', name: '', module: '', description: '', isActive: true,
};

const emptyPackageForm: PackageFormData = {
  code: '', name: '', description: '', orderIndex: '', isActive: true,
};

// ─────────────────────────────────────────────────────────────────────────────
// Main component
// ─────────────────────────────────────────────────────────────────────────────

const PermissionsManagementPage: React.FC = () => {
  const { isMobile, isTablet } = useResponsive();
  const toast = useAppToast();
  const slideoutWidth = isMobile ? '100%' : isTablet ? '520px' : '620px';
  const currentUser = useAppSelector((state) => state.auth.user);
  const currentUsername = currentUser?.username ?? 'admin';

  const [activeTab, setActiveTab] = useState('permissions');

  // ── Permissions state ──────────────────────────────────────────────────────
  const [permissions, setPermissions]           = useState<BffPermissionDto[]>([]);
  const [permLoading, setPermLoading]           = useState(true);
  const [permSearch, setPermSearch]             = useState('');
  const [permModuleFilter, setPermModuleFilter] = useState('');
  const [permFormOpen, setPermFormOpen]         = useState(false);
  const [editingPerm, setEditingPerm]           = useState<BffPermissionDto | null>(null);
  const [permForm, setPermForm]                 = useState<PermissionFormData>(emptyPermissionForm);
  const [permFormError, setPermFormError]       = useState('');
  const [permSaving, setPermSaving]             = useState(false);
  const [deletePermId, setDeletePermId]         = useState<string | null>(null);
  const [permDeleting, setPermDeleting]         = useState(false);

  // ── Packages state ─────────────────────────────────────────────────────────
  const [packages, setPackages]                         = useState<BffFeaturePackageDto[]>([]);
  const [pkgLoading, setPkgLoading]                     = useState(true);
  const [pkgSearch, setPkgSearch]                       = useState('');
  const [pkgFormOpen, setPkgFormOpen]                   = useState(false);
  const [editingPkg, setEditingPkg]                     = useState<BffFeaturePackageDto | null>(null);
  const [pkgForm, setPkgForm]                           = useState<PackageFormData>(emptyPackageForm);
  const [pkgFormError, setPkgFormError]                 = useState('');
  const [pkgSaving, setPkgSaving]                       = useState(false);
  const [deletePkgId, setDeletePkgId]                   = useState<string | null>(null);
  const [pkgDeleting, setPkgDeleting]                   = useState(false);

  // Permission assignment for a package
  const [managePermPkgId, setManagePermPkgId]           = useState<string | null>(null);
  const [managePermPkg, setManagePermPkg]               = useState<BffFeaturePackageDto | null>(null);
  const [selectedPermIds, setSelectedPermIds]           = useState<Set<string>>(new Set());
  const [assigningPerms, setAssigningPerms]             = useState(false);

  // ── Load data ──────────────────────────────────────────────────────────────
  const permCancelRef = useRef(false);
  const pkgCancelRef  = useRef(false);

  const loadPermissions = useCallback(async () => {
    permCancelRef.current = false;
    setPermLoading(true);
    try {
      const data = await adminService.getPermissions();
      if (permCancelRef.current) return;
      setPermissions(data);
    } catch {
      if (!permCancelRef.current) toast.error('Không thể tải danh sách quyền');
    } finally {
      if (!permCancelRef.current) setPermLoading(false);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Helper to normalize package from API response
  const normalizePackage = (pkg: BffFeaturePackageDto): BffFeaturePackageDto => {
    const codes: string[] = pkg.permissions?.length
      ? pkg.permissions.map((p) => p.code)
      : (pkg.PermissionCodes ?? []);
    return {
      ...pkg,
      permissions: pkg.permissions?.length
        ? pkg.permissions
        : codes.map((code) => ({ id: code, code, name: code, module: '', description: '', isActive: true })),
      permissionCount: pkg.permissionCount ?? codes.length,
    };
  };

  const loadPackages = useCallback(async () => {
    pkgCancelRef.current = false;
    setPkgLoading(true);
    try {
      const raw = await adminService.getPackages();
      const data = raw.map(normalizePackage);
      if (pkgCancelRef.current) return;
      setPackages(data);
    } catch {
      if (!pkgCancelRef.current) toast.error('Không thể tải danh sách gói');
    } finally {
      if (!pkgCancelRef.current) setPkgLoading(false);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const t = setTimeout(() => { loadPermissions(); loadPackages(); }, 0);
    return () => { clearTimeout(t); permCancelRef.current = true; pkgCancelRef.current = true; };
  }, [loadPermissions, loadPackages]);

  // ── Derived data ───────────────────────────────────────────────────────────
  const modules = Array.from(new Set(permissions.map((p) => p.module))).sort();

  const filteredPermissions = permissions.filter((p) => {
    const matchSearch =
      !permSearch ||
      p.name.toLowerCase().includes(permSearch.toLowerCase()) ||
      p.code.toLowerCase().includes(permSearch.toLowerCase());
    const matchModule = !permModuleFilter || p.module === permModuleFilter;
    return matchSearch && matchModule;
  });

  // Group by module
  const permsByModule = filteredPermissions.reduce<Record<string, BffPermissionDto[]>>(
    (acc, p) => {
      (acc[p.module] = acc[p.module] ?? []).push(p);
      return acc;
    },
    {},
  );

  const filteredPackages = packages.filter(
    (p) =>
      !pkgSearch ||
      p.name.toLowerCase().includes(pkgSearch.toLowerCase()) ||
      p.code.toLowerCase().includes(pkgSearch.toLowerCase()),
  );

  // ── Permission CRUD ────────────────────────────────────────────────────────
  const openAddPerm = () => {
    setEditingPerm(null);
    setPermForm(emptyPermissionForm);
    setPermFormError('');
    setPermFormOpen(true);
  };

  const openEditPerm = (perm: BffPermissionDto, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPerm(perm);
    setPermForm({ code: perm.code, name: perm.name, module: perm.module, description: perm.description, isActive: perm.isActive });
    setPermFormError('');
    setPermFormOpen(true);
  };

  const handlePermFormChange = <K extends keyof PermissionFormData>(key: K, val: PermissionFormData[K]) => {
    setPermForm((prev) => ({ ...prev, [key]: val }));
  };

  const handleSavePerm = async () => {
    if (!permForm.code.trim() || !permForm.name.trim() || !permForm.module.trim()) {
      setPermFormError('Vui lòng điền đầy đủ các trường bắt buộc');
      return;
    }
    setPermSaving(true);
    try {
      if (editingPerm) {
        const updated = await adminService.updatePermission(editingPerm.id, {
          name: permForm.name,
          module: permForm.module,
          description: permForm.description || undefined,
          isActive: permForm.isActive,
        });
        setPermissions((prev) => prev.map((p) => (p.id === editingPerm.id ? updated : p)));
        toast.success('Đã cập nhật quyền thành công');
      } else {
        const created = await adminService.createPermission({
          code: permForm.code,
          name: permForm.name,
          module: permForm.module,
          description: permForm.description || undefined,
        });
        setPermissions((prev) => [...prev, created]);
        toast.success('Đã tạo quyền mới thành công');
      }
      setPermFormOpen(false);
    } catch {
      setPermFormError('Đã có lỗi xảy ra. Vui lòng thử lại.');
    } finally {
      setPermSaving(false);
    }
  };

  const handleDeletePerm = async () => {
    if (!deletePermId) return;
    setPermDeleting(true);
    try {
      await adminService.deletePermission(deletePermId);
      setPermissions((prev) => prev.filter((p) => p.id !== deletePermId));
      toast.success('Đã xóa quyền');
      setDeletePermId(null);
    } catch {
      toast.error('Không thể xóa quyền');
    } finally {
      setPermDeleting(false);
    }
  };

  // ── Package CRUD ───────────────────────────────────────────────────────────
  const openAddPkg = () => {
    setEditingPkg(null);
    setPkgForm(emptyPackageForm);
    setPkgFormError('');
    setPkgFormOpen(true);
  };

  const openEditPkg = (pkg: BffFeaturePackageDto, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPkg(pkg);
    setPkgForm({ code: pkg.code, name: pkg.name, description: pkg.description, orderIndex: String(pkg.orderIndex), isActive: pkg.isActive });
    setPkgFormError('');
    setPkgFormOpen(true);
  };

  const handlePkgFormChange = <K extends keyof PackageFormData>(key: K, val: PackageFormData[K]) => {
    setPkgForm((prev) => ({ ...prev, [key]: val }));
  };

  const handleSavePkg = async () => {
    if (!pkgForm.code.trim() || !pkgForm.name.trim()) {
      setPkgFormError('Vui lòng điền đầy đủ các trường bắt buộc');
      return;
    }
    setPkgSaving(true);
    try {
      if (editingPkg) {
        const updated = await adminService.updatePackage(editingPkg.id, {
          name: pkgForm.name,
          description: pkgForm.description || undefined,
          orderIndex: pkgForm.orderIndex ? Number(pkgForm.orderIndex) : editingPkg.orderIndex,
          isActive: pkgForm.isActive,
        });
        setPackages((prev) => prev.map((p) => (p.id === editingPkg.id ? normalizePackage(updated) : p)));
        toast.success('Đã cập nhật gói thành công');
      } else {
        const created = await adminService.createPackage({
          code: pkgForm.code,
          name: pkgForm.name,
          description: pkgForm.description || undefined,
          orderIndex: pkgForm.orderIndex ? Number(pkgForm.orderIndex) : (packages.length + 1),
          permissionIds: [],
        });
        setPackages((prev) => [...prev, normalizePackage(created)]);
        toast.success('Đã tạo gói mới thành công');
      }
      setPkgFormOpen(false);
    } catch {
      setPkgFormError('Đã có lỗi xảy ra. Vui lòng thử lại.');
    } finally {
      setPkgSaving(false);
    }
  };

  const handleDeletePkg = async () => {
    if (!deletePkgId) return;
    setPkgDeleting(true);
    try {
      await adminService.deletePackage(deletePkgId);
      setPackages((prev) => prev.filter((p) => p.id !== deletePkgId));
      toast.success('Đã xóa gói');
      setDeletePkgId(null);
    } catch {
      toast.error('Không thể xóa gói');
    } finally {
      setPkgDeleting(false);
    }
  };

  // ── Package permission assignment ──────────────────────────────────────────
  const openManagePerms = (pkg: BffFeaturePackageDto, e: React.MouseEvent) => {
    e.stopPropagation();
    setManagePermPkgId(pkg.id);
    setManagePermPkg(pkg);
    // Cross-reference package permission codes with the full permissions list to get real UUIDs
    // (GET /admin/packages returns PermissionCodes:string[], not UUIDs)
    const pkgCodes = new Set((pkg.permissions ?? []).map((p) => p.code));
    const matchedIds = permissions
      .filter((p) => pkgCodes.has(p.code))
      .map((p) => p.id);
    setSelectedPermIds(new Set(matchedIds));
  };

  const closeManagePerms = () => {
    setManagePermPkgId(null);
    setManagePermPkg(null);
  };

  const togglePermForPkg = (permId: string) => {
    setSelectedPermIds((prev) => {
      const next = new Set(prev);
      if (next.has(permId)) next.delete(permId);
      else next.add(permId);
      return next;
    });
  };

  const handleSavePackagePerms = async () => {
    if (!managePermPkgId) return;
    setAssigningPerms(true);
    try {
      await adminService.assignPermissionsToPackage(managePermPkgId, {
        permissionIds: Array.from(selectedPermIds),
        assignedBy: currentUsername,
      });
      setPackages((prev) =>
        prev.map((p) => {
          if (p.id !== managePermPkgId) return p;
          const perms = permissions.filter((pm) => selectedPermIds.has(pm.id));
          return { ...p, permissions: perms, permissionCount: perms.length };
        }),
      );
      toast.success('Đã cập nhật quyền cho gói');
      closeManagePerms();
    } catch {
      toast.error('Không thể cập nhật quyền cho gói');
    } finally {
      setAssigningPerms(false);
    }
  };

  // ─────────────────────────────────────────────────────────────────────────
  // Tabs definition
  // ─────────────────────────────────────────────────────────────────────────

  const tabs = [
    {
      id: 'permissions',
      label: 'Quyền truy cập',
      icon: 'fas fa-key',
      badge: permissions.length,
    },
    {
      id: 'packages',
      label: 'Gói tính năng',
      icon: 'fas fa-cube',
      badge: packages.length,
    },
  ];

  // ─────────────────────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────────────────────

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <h1 className={styles.title}>
            <i className="fas fa-shield-alt" />
            Quản lý phân quyền
          </h1>
          <span className={styles.subtitle}>
            Cấu hình quyền truy cập và gói tính năng
          </span>
        </div>
      </div>

      {/* Tabs */}
      <Tabs
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        variant="underline"
      />

      {/* ══ PERMISSIONS TAB ══════════════════════════════════════════════════ */}
      {activeTab === 'permissions' && (
        <div className={styles.tabContent}>
          {/* Toolbar */}
          <div className={styles.toolbar}>
            <div className={styles.searchWrapper}>
              <i className={`fas fa-search ${styles.searchIcon}`} />
              <input
                type="text"
                className={styles.searchInput}
                placeholder="Tìm quyền..."
                value={permSearch}
                onChange={(e) => setPermSearch(e.target.value)}
              />
            </div>
            <select
              className={styles.filterSelect}
              value={permModuleFilter}
              onChange={(e) => setPermModuleFilter(e.target.value)}
            >
              <option value="">Tất cả module</option>
              {modules.map((m) => (
                <option key={m} value={m}>{m}</option>
              ))}
            </select>
            <button className={styles.addBtn} onClick={openAddPerm}>
              <i className="fas fa-plus" /> Thêm quyền
            </button>
          </div>

          {permLoading ? (
            <div className={styles.loadingState}>
              <i className="fas fa-spinner fa-spin" />
              <span>Đang tải...</span>
            </div>
          ) : filteredPermissions.length === 0 ? (
            <div className={styles.emptyState}>
              <i className="fas fa-key" />
              <p>Không tìm thấy quyền nào</p>
            </div>
          ) : (
            <div className={styles.moduleGroups}>
              {Object.entries(permsByModule).sort(([a], [b]) => a.localeCompare(b)).map(([module, perms]) => (
                <div key={module} className={styles.moduleGroup}>
                  <div className={styles.moduleGroupHeader}>
                    <span className={styles.moduleLabel}>
                      <i className="fas fa-tag" />
                      {module}
                    </span>
                    <span className={styles.moduleCount}>{perms.length}</span>
                  </div>
                  <div className={styles.permGrid}>
                    {perms.map((perm) => (
                      <div key={perm.id} className={`${styles.permCard} ${!perm.isActive ? styles.permCardInactive : ''}`}>
                        <div className={styles.permCardTop}>
                          <span className={styles.permCode}>{perm.code}</span>
                          <div className={styles.permCardActions}>
                            <button
                              className={styles.editSmallBtn}
                              onClick={(e) => openEditPerm(perm, e)}
                              title="Sửa"
                            >
                              <i className="fas fa-pen" />
                            </button>
                            <button
                              className={styles.deleteSmallBtn}
                              onClick={(e) => { e.stopPropagation(); setDeletePermId(perm.id); }}
                              title="Xóa"
                            >
                              <i className="fas fa-trash" />
                            </button>
                          </div>
                        </div>
                        <div className={styles.permName}>{perm.name}</div>
                        {perm.description && (
                          <div className={styles.permDesc}>{perm.description}</div>
                        )}
                        {!perm.isActive && (
                          <span className={styles.inactiveBadge}>Không kích hoạt</span>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ══ PACKAGES TAB ═════════════════════════════════════════════════════ */}
      {activeTab === 'packages' && (
        <div className={styles.tabContent}>
          {/* Toolbar */}
          <div className={styles.toolbar}>
            <div className={styles.searchWrapper}>
              <i className={`fas fa-search ${styles.searchIcon}`} />
              <input
                type="text"
                className={styles.searchInput}
                placeholder="Tìm gói..."
                value={pkgSearch}
                onChange={(e) => setPkgSearch(e.target.value)}
              />
            </div>
            <button className={styles.addBtn} onClick={openAddPkg}>
              <i className="fas fa-plus" /> Thêm gói
            </button>
          </div>

          {pkgLoading ? (
            <div className={styles.loadingState}>
              <i className="fas fa-spinner fa-spin" />
              <span>Đang tải...</span>
            </div>
          ) : filteredPackages.length === 0 ? (
            <div className={styles.emptyState}>
              <i className="fas fa-cube" />
              <p>Không tìm thấy gói nào</p>
            </div>
          ) : (
            <div className={styles.pkgGrid}>
              {filteredPackages.map((pkg) => (
                <div key={pkg.id} className={`${styles.pkgCard} ${!pkg.isActive ? styles.pkgCardInactive : ''}`}>
                  <div className={styles.pkgCardHeader}>
                    <div>
                      <div className={styles.pkgCode}>{pkg.code}</div>
                      <div className={styles.pkgName}>{pkg.name}</div>
                    </div>
                    <div className={styles.pkgActions}>
                      <button
                        className={styles.managePermsBtn}
                        onClick={(e) => openManagePerms(pkg, e)}
                        title="Quản lý quyền"
                      >
                        <i className="fas fa-key" />
                      </button>
                      <button
                        className={styles.editSmallBtn}
                        onClick={(e) => openEditPkg(pkg, e)}
                        title="Sửa"
                      >
                        <i className="fas fa-pen" />
                      </button>
                      <button
                        className={styles.deleteSmallBtn}
                        onClick={(e) => { e.stopPropagation(); setDeletePkgId(pkg.id); }}
                        title="Xóa"
                      >
                        <i className="fas fa-trash" />
                      </button>
                    </div>
                  </div>
                  {pkg.description && (
                    <div className={styles.pkgDesc}>{pkg.description}</div>
                  )}
                  <div className={styles.pkgFooter}>
                    <span className={styles.pkgPermCount}>
                      <i className="fas fa-key" />
                      {pkg.permissionCount} quyền
                    </span>
                    {!pkg.isActive && (
                      <span className={styles.inactiveBadge}>Không kích hoạt</span>
                    )}
                    <span className={styles.pkgOrder}>
                      <i className="fas fa-sort-numeric-up" />
                      #{pkg.orderIndex}
                    </span>
                  </div>
                  {pkg.permissions.length > 0 && (
                    <div className={styles.pkgPermTags}>
                      {pkg.permissions.slice(0, 5).map((p) => (
                        <span key={p.id} className={styles.permTag}>{p.code}</span>
                      ))}
                      {pkg.permissions.length > 5 && (
                        <span className={styles.permTagMore}>+{pkg.permissions.length - 5}</span>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ── Permission Create/Edit Slideout ── */}
      <Slideout
        isOpen={permFormOpen}
        onClose={() => setPermFormOpen(false)}
        title={
          <span className={styles.slideoutTitle}>
            <i className={editingPerm ? 'fas fa-key' : 'fas fa-plus-circle'} style={{ color: 'var(--primary-color)' }} />
            {editingPerm ? 'Sửa quyền' : 'Thêm quyền mới'}
          </span>
        }
        width={slideoutWidth}
        customFooter={
          <>
            <button className={styles.cancelBtn} onClick={() => setPermFormOpen(false)} disabled={permSaving}>
              Hủy
            </button>
            <button className={styles.saveBtn} onClick={handleSavePerm} disabled={permSaving}>
              {permSaving
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-save" /> {editingPerm ? 'Cập nhật' : 'Tạo mới'}</>
              }
            </button>
          </>
        }
      >
        <div className={styles.form}>
          {permFormError && (
            <div className={styles.formError}>
              <i className="fas fa-exclamation-circle" />
              {permFormError}
            </div>
          )}
          <div className={styles.formGrid}>
            <div className={styles.formGroup}>
              <label className={styles.label}>Mã quyền <span className={styles.required}>*</span></label>
              <input
                type="text"
                className={styles.input}
                value={permForm.code}
                onChange={(e) => handlePermFormChange('code', e.target.value)}
                placeholder="dashboard.view"
                disabled={!!editingPerm}
              />
              {!editingPerm && (
                <span className={styles.hint}>Dùng dấu chấm, ví dụ: module.action</span>
              )}
            </div>
            <div className={styles.formGroup}>
              <label className={styles.label}>Module <span className={styles.required}>*</span></label>
              <input
                type="text"
                className={styles.input}
                value={permForm.module}
                onChange={(e) => handlePermFormChange('module', e.target.value)}
                placeholder="Dashboard"
                list="modules-list"
              />
              <datalist id="modules-list">
                {modules.map((m) => <option key={m} value={m} />)}
              </datalist>
            </div>
            <div className={`${styles.formGroup} ${styles.fullWidth}`}>
              <label className={styles.label}>Tên hiển thị <span className={styles.required}>*</span></label>
              <input
                type="text"
                className={styles.input}
                value={permForm.name}
                onChange={(e) => handlePermFormChange('name', e.target.value)}
                placeholder="Xem Dashboard"
              />
            </div>
            <div className={`${styles.formGroup} ${styles.fullWidth}`}>
              <label className={styles.label}>Mô tả</label>
              <input
                type="text"
                className={styles.input}
                value={permForm.description}
                onChange={(e) => handlePermFormChange('description', e.target.value)}
                placeholder="Mô tả ngắn về quyền này..."
              />
            </div>
            {editingPerm && (
              <div className={styles.formGroup}>
                <label className={styles.checkboxRow}>
                  <input
                    type="checkbox"
                    checked={permForm.isActive}
                    onChange={(e) => handlePermFormChange('isActive', e.target.checked)}
                  />
                  <span>Kích hoạt</span>
                </label>
              </div>
            )}
          </div>
        </div>
      </Slideout>

      {/* ── Package Create/Edit Slideout ── */}
      <Slideout
        isOpen={pkgFormOpen}
        onClose={() => setPkgFormOpen(false)}
        title={
          <span className={styles.slideoutTitle}>
            <i className={editingPkg ? 'fas fa-cube' : 'fas fa-plus-circle'} style={{ color: 'var(--primary-color)' }} />
            {editingPkg ? 'Sửa gói tính năng' : 'Thêm gói mới'}
          </span>
        }
        width={slideoutWidth}
        customFooter={
          <>
            <button className={styles.cancelBtn} onClick={() => setPkgFormOpen(false)} disabled={pkgSaving}>
              Hủy
            </button>
            <button className={styles.saveBtn} onClick={handleSavePkg} disabled={pkgSaving}>
              {pkgSaving
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-save" /> {editingPkg ? 'Cập nhật' : 'Tạo mới'}</>
              }
            </button>
          </>
        }
      >
        <div className={styles.form}>
          {pkgFormError && (
            <div className={styles.formError}>
              <i className="fas fa-exclamation-circle" />
              {pkgFormError}
            </div>
          )}
          <div className={styles.formGrid}>
            <div className={styles.formGroup}>
              <label className={styles.label}>Mã gói <span className={styles.required}>*</span></label>
              <input
                type="text"
                className={styles.input}
                value={pkgForm.code}
                onChange={(e) => handlePkgFormChange('code', e.target.value)}
                placeholder="BASIC"
                disabled={!!editingPkg}
              />
            </div>
            <div className={styles.formGroup}>
              <label className={styles.label}>Thứ tự</label>
              <input
                type="number"
                className={styles.input}
                value={pkgForm.orderIndex}
                onChange={(e) => handlePkgFormChange('orderIndex', e.target.value)}
                placeholder="1"
                min={1}
              />
            </div>
            <div className={`${styles.formGroup} ${styles.fullWidth}`}>
              <label className={styles.label}>Tên gói <span className={styles.required}>*</span></label>
              <input
                type="text"
                className={styles.input}
                value={pkgForm.name}
                onChange={(e) => handlePkgFormChange('name', e.target.value)}
                placeholder="Gói Cơ bản"
              />
            </div>
            <div className={`${styles.formGroup} ${styles.fullWidth}`}>
              <label className={styles.label}>Mô tả</label>
              <input
                type="text"
                className={styles.input}
                value={pkgForm.description}
                onChange={(e) => handlePkgFormChange('description', e.target.value)}
                placeholder="Mô tả về gói..."
              />
            </div>
            {editingPkg && (
              <div className={styles.formGroup}>
                <label className={styles.checkboxRow}>
                  <input
                    type="checkbox"
                    checked={pkgForm.isActive}
                    onChange={(e) => handlePkgFormChange('isActive', e.target.checked)}
                  />
                  <span>Kích hoạt</span>
                </label>
              </div>
            )}
          </div>
        </div>
      </Slideout>

      {/* ── Manage Package Permissions Slideout ── */}
      <Slideout
        isOpen={!!managePermPkgId}
        onClose={closeManagePerms}
        title={
          <span className={styles.slideoutTitle}>
            <i className="fas fa-key" style={{ color: 'var(--primary-color)' }} />
            Phân quyền: {managePermPkg?.name}
          </span>
        }
        width={slideoutWidth}
        customFooter={
          <>
            <button className={styles.cancelBtn} onClick={closeManagePerms} disabled={assigningPerms}>
              Hủy
            </button>
            <button className={styles.saveBtn} onClick={handleSavePackagePerms} disabled={assigningPerms}>
              {assigningPerms
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-save" /> Lưu phân quyền ({selectedPermIds.size})</>
              }
            </button>
          </>
        }
      >
        <div className={styles.managePermsContent}>
          <div className={styles.managePermsInfo}>
            <i className="fas fa-info-circle" />
            Chọn các quyền sẽ được gán cho gói <strong>{managePermPkg?.code}</strong>.
            Thay đổi sẽ thay thế toàn bộ danh sách quyền hiện tại.
          </div>
          <div className={styles.selectAllRow}>
            <label className={styles.checkboxRow}>
              <input
                type="checkbox"
                checked={selectedPermIds.size === permissions.length && permissions.length > 0}
                onChange={(e) => {
                  if (e.target.checked) setSelectedPermIds(new Set(permissions.map((p) => p.id)));
                  else setSelectedPermIds(new Set());
                }}
              />
              <span className={styles.selectAllLabel}>Chọn tất cả ({permissions.length})</span>
            </label>
          </div>
          {Object.entries(
            permissions.reduce<Record<string, BffPermissionDto[]>>((acc, p) => {
              (acc[p.module] = acc[p.module] ?? []).push(p);
              return acc;
            }, {}),
          )
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([module, perms]) => (
              <div key={module} className={styles.permCheckGroup}>
                <div className={styles.permCheckGroupHeader}>{module}</div>
                <div className={styles.permCheckList}>
                  {perms.map((perm) => (
                    <label key={perm.id} className={styles.permCheckItem}>
                      <input
                        type="checkbox"
                        checked={selectedPermIds.has(perm.id)}
                        onChange={() => togglePermForPkg(perm.id)}
                      />
                      <div className={styles.permCheckInfo}>
                        <span className={styles.permCheckCode}>{perm.code}</span>
                        <span className={styles.permCheckName}>{perm.name}</span>
                      </div>
                    </label>
                  ))}
                </div>
              </div>
            ))}
        </div>
      </Slideout>

      {/* ── Delete Permission Confirm ── */}
      <Slideout
        isOpen={!!deletePermId}
        onClose={() => { if (!permDeleting) setDeletePermId(null); }}
        title="Xác nhận xóa quyền"
        width="420px"
        customFooter={
          <>
            <button className={styles.cancelBtn} onClick={() => setDeletePermId(null)} disabled={permDeleting}>
              Hủy
            </button>
            <button className={styles.deleteConfirmBtn} onClick={handleDeletePerm} disabled={permDeleting}>
              {permDeleting ? <><i className="fas fa-spinner fa-spin" /> Đang xóa...</> : <><i className="fas fa-trash" /> Xóa</>}
            </button>
          </>
        }
      >
        <div className={styles.confirmBody}>
          <div className={`${styles.confirmIcon} ${styles.dangerIcon}`}>
            <i className="fas fa-exclamation-triangle" />
          </div>
          <h3 className={styles.confirmTitle}>Xóa quyền này?</h3>
          <p className={styles.confirmText}>Hành động này không thể hoàn tác. Quyền sẽ bị xóa khỏi tất cả các gói tính năng.</p>
        </div>
      </Slideout>

      {/* ── Delete Package Confirm ── */}
      <Slideout
        isOpen={!!deletePkgId}
        onClose={() => { if (!pkgDeleting) setDeletePkgId(null); }}
        title="Xác nhận xóa gói"
        width="420px"
        customFooter={
          <>
            <button className={styles.cancelBtn} onClick={() => setDeletePkgId(null)} disabled={pkgDeleting}>
              Hủy
            </button>
            <button className={styles.deleteConfirmBtn} onClick={handleDeletePkg} disabled={pkgDeleting}>
              {pkgDeleting ? <><i className="fas fa-spinner fa-spin" /> Đang xóa...</> : <><i className="fas fa-trash" /> Xóa</>}
            </button>
          </>
        }
      >
        <div className={styles.confirmBody}>
          <div className={`${styles.confirmIcon} ${styles.dangerIcon}`}>
            <i className="fas fa-exclamation-triangle" />
          </div>
          <h3 className={styles.confirmTitle}>Xóa gói tính năng này?</h3>
          <p className={styles.confirmText}>Hành động này không thể hoàn tác. Người dùng đang sử dụng gói này sẽ mất quyền truy cập.</p>
        </div>
      </Slideout>
    </div>
  );
};

export default PermissionsManagementPage;
