import React, { useState, useMemo, useRef, useCallback, useEffect } from 'react';
import { Input } from '../../../components/common/Input';
import { Select, SelectOption } from '../../../components/common/Select';
import { MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import { useResponsive } from '../../../hooks/useResponsive';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './MedicalIncidentReportFilters.module.css';

const CURRENT_YEAR = new Date().getFullYear();

interface Props {
  filters: MedicalIncidentReportFilters;
  onChange: (f: MedicalIncidentReportFilters) => void;
  onClear: () => void;
}

export const MedicalIncidentReportFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
}) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);
  const { departmentOptions } = useFormOptions('incident-list');

  // ref on the toggle button to compute fixed-position coordinates
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [dropdownStyle, setDropdownStyle] = useState<React.CSSProperties>({});

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa/phòng' }, ...departmentOptions],
    [departmentOptions],
  );

  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.dateFrom)     count++;
    if (filters.dateTo)       count++;
    if (filters.departmentId) count++;
    // year == current year is the default — don't count it as "active"
    if (filters.year && filters.year !== CURRENT_YEAR) count++;
    return count;
  }, [filters]);

  const hasActiveFilters = activeFilterCount > 0 ||
    Boolean(filters.dateFrom) ||
    Boolean(filters.dateTo) ||
    Boolean(filters.departmentId);

  /** Compute dropdown position from button's viewport rect so it breaks out of any overflow parent. */
  const computeDropdownStyle = useCallback(() => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    const panelWidth = Math.min(300, window.innerWidth - 16);
    const centeredLeft = Math.max(8, (window.innerWidth - panelWidth) / 2);
    setDropdownStyle({
      top:   rect.bottom + 8,
      left:  centeredLeft,
      width: panelWidth,
    });
  }, []);

  const handleToggle = () => {
    if (!isExpanded) computeDropdownStyle();
    setIsExpanded((v) => !v);
  };

  const handleClose = () => setIsExpanded(false);

  // Close on scroll/resize
  useEffect(() => {
    if (!isExpanded) return;
    const close = () => setIsExpanded(false);
    window.addEventListener('scroll',  close, { passive: true, capture: true });
    window.addEventListener('resize',  close, { passive: true });
    return () => {
      window.removeEventListener('scroll',  close, { capture: true });
      window.removeEventListener('resize',  close);
    };
  }, [isExpanded]);

  const handleYearChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    if (!isNaN(val) && val > 1990 && val <= CURRENT_YEAR + 1) {
      onChange({ ...filters, year: val, dateFrom: undefined, dateTo: undefined });
    }
  };

  const handleDateFromChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ ...filters, dateFrom: e.target.value || undefined, year: undefined });
  };

  const handleDateToChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ ...filters, dateTo: e.target.value || undefined, year: undefined });
  };

  const handleDeptChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({ ...filters, departmentId: e.target.value || undefined });
  };

  // ── Mobile: toggle button + backdrop + dropdown panel ─────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && (
          <div className={styles.filterBackdrop} onClick={handleClose} />
        )}

        <div className={styles.filterDropdownWrapper}>
          <button
            ref={buttonRef}
            className={styles.filterToggle}
            onClick={handleToggle}
            aria-expanded={isExpanded}
            aria-label="Toggle filters"
            type="button"
          >
            <i className="fas fa-filter" />
            <span>Lọc</span>
            {activeFilterCount > 0 && (
              <span className={styles.filterBadge}>{activeFilterCount}</span>
            )}
            <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
          </button>

          {isExpanded && (
            <div className={styles.mobileFilters} style={dropdownStyle}>
              <Input
                label="Năm"
                type="number"
                min={2000}
                max={CURRENT_YEAR + 1}
                value={filters.year ?? ''}
                onChange={handleYearChange}
                placeholder={String(CURRENT_YEAR)}
                size="small"
                fullWidth
              />
              <Input
                label="Từ ngày"
                type="date"
                value={filters.dateFrom ?? ''}
                onChange={handleDateFromChange}
                size="small"
                fullWidth
              />
              <Input
                label="Đến ngày"
                type="date"
                value={filters.dateTo ?? ''}
                onChange={handleDateToChange}
                size="small"
                fullWidth
              />
              <Select
                label="Khoa/Phòng"
                options={allDeptOptions}
                value={filters.departmentId ?? ''}
                onChange={handleDeptChange}
                size="small"
                fullWidth
              />
              {hasActiveFilters && (
                <button
                  className={styles.clearFiltersButton}
                  onClick={() => { onClear(); handleClose(); }}
                  type="button"
                >
                  <i className="fas fa-times-circle" />
                  <span>Xóa bộ lọc</span>
                </button>
              )}
            </div>
          )}
        </div>
      </>
    );
  }

  // ── Desktop: horizontal row ────────────────────────────────────────────────
  return (
    <div className={styles.filters}>
      <Input
        label="Năm"
        type="number"
        min={2000}
        max={CURRENT_YEAR + 1}
        value={filters.year ?? ''}
        onChange={handleYearChange}
        placeholder={String(CURRENT_YEAR)}
        size="small"
        className={styles.yearInput}
      />
      <Input
        label="Từ ngày"
        type="date"
        value={filters.dateFrom ?? ''}
        onChange={handleDateFromChange}
        size="small"
      />
      <Input
        label="Đến ngày"
        type="date"
        value={filters.dateTo ?? ''}
        onChange={handleDateToChange}
        size="small"
      />
      <Select
        label="Khoa/Phòng"
        options={allDeptOptions}
        value={filters.departmentId ?? ''}
        onChange={handleDeptChange}
        size="small"
      />
      {hasActiveFilters && (
        <button
          className={styles.clearFiltersButtonDesktop}
          onClick={onClear}
          type="button"
          title="Xóa bộ lọc"
        >
          <i className="fas fa-times-circle" />
          <span>Xóa bộ lọc</span>
        </button>
      )}
    </div>
  );
};
