import React from 'react';
import { PerformanceScore as PerformanceScoreType } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './PerformanceScore.module.css';

interface PerformanceScoreProps {
  data: PerformanceScoreType;
}

export const PerformanceScore: React.FC<PerformanceScoreProps> = ({ data }) => {
  return (
    <Card className={styles.scoreCard}>
      <h3 className={styles.title}>
        <i className="fas fa-gauge-high" style={{ color: 'var(--success-color)' }}></i>
        Điểm hiệu suất
      </h3>
      <div className={styles.scoreOverall}>
        <div className={styles.scoreValue}>{data.overall}</div>
        <div className={styles.scoreRating}>{data.rating}</div>
        <div className={styles.scorePercentile}>
          Top {100 - data.percentile}% trong tổ chức
        </div>
      </div>
      <div className={styles.breakdown}>
        <div className={styles.breakdownItem}>
          <div className={styles.breakdownLabel}>
            <span>Chất lượng</span>
            <span className={styles.breakdownValue}>{data.breakdown.quality}%</span>
          </div>
          <div className={styles.progressBar}>
            <div
              className={styles.progressFill}
              style={{
                width: `${data.breakdown.quality}%`,
                backgroundColor: 'var(--success-color)',
              }}
            ></div>
          </div>
        </div>
        <div className={styles.breakdownItem}>
          <div className={styles.breakdownLabel}>
            <span>Tốc độ</span>
            <span className={styles.breakdownValue}>{data.breakdown.speed}%</span>
          </div>
          <div className={styles.progressBar}>
            <div
              className={styles.progressFill}
              style={{
                width: `${data.breakdown.speed}%`,
                backgroundColor: 'var(--info-color)',
              }}
            ></div>
          </div>
        </div>
        <div className={styles.breakdownItem}>
          <div className={styles.breakdownLabel}>
            <span>Tuân thủ SLA</span>
            <span className={styles.breakdownValue}>{data.breakdown.slaCompliance}%</span>
          </div>
          <div className={styles.progressBar}>
            <div
              className={styles.progressFill}
              style={{
                width: `${data.breakdown.slaCompliance}%`,
                backgroundColor: 'var(--primary-color)',
              }}
            ></div>
          </div>
        </div>
      </div>
    </Card>
  );
};
