/**
 * Mappers: BFF DTOs → frontend model types for History.
 */

import type { BffHistoryItemDto, BffHistoryStatsDto } from './responseModel';
import {
  HistoryItemType,
  HistoryActionType,
  type HistoryItem,
  type HistoryStats,
} from '../../models/History';

/** Map BFF activity type string → HistoryActionType enum. */
const ACTION_TYPE_MAP: Record<string, HistoryActionType> = {
  created:          HistoryActionType.Created,
  assigned:         HistoryActionType.Assigned,
  started:          HistoryActionType.Started,
  completed:        HistoryActionType.Completed,
  resolved:         HistoryActionType.Resolved,
  closed:           HistoryActionType.Closed,
  cancelled:        HistoryActionType.Cancelled,
  reopened:         HistoryActionType.Reopened,
  priority_changed: HistoryActionType.PriorityChanged,
  status_changed:   HistoryActionType.StatusChanged,
};

export const mapBffHistoryItem = (dto: BffHistoryItemDto): HistoryItem => {
  const createdAt = dto.createdAt;
  return {
    id:                dto.id,
    type:              dto.domain === 'task' ? HistoryItemType.Task : HistoryItemType.Ticket,
    entityId:          dto.entityId,
    entityCode:        dto.entityNumber,
    entityTitle:       dto.entityTitle,
    actionType:        ACTION_TYPE_MAP[dto.type] ?? HistoryActionType.StatusChanged,
    actionDescription: dto.description,
    priority:          (dto.priority ?? 'medium') as HistoryItem['priority'],
    status:            dto.toStatus ?? dto.currentStatus ?? dto.fromStatus ?? 'unknown',
    completedAt:       createdAt,
    createdAt,
    updatedAt:         createdAt,
    metadata:          dto.fromStatus || dto.toStatus
      ? { oldStatus: dto.fromStatus as any, newStatus: dto.toStatus as any }
      : undefined,
  };
};

export const mapBffHistoryStats = (dto: BffHistoryStatsDto): HistoryStats => ({
  totalCompleted:     dto.totalCompleted,
  completedThisMonth: dto.completedThisMonth,
  completedThisWeek:  dto.completedThisWeek,
  totalTimeSpent:     dto.totalTimeSpent,
  averageRating:      dto.averageRating,
  onTimePercentage:   dto.onTimePercentage,
  slaBreaches:        dto.slaBreaches,
});
