import { UUID, Timestamps } from './common';

export interface Ticket extends Timestamps {
  id: UUID;
  idCode?: string; // "TKT-YYYYMMDD-0001"
  title: string;
  description: string;
  priority: TicketPriority;
  status: TicketStatus;
  category?: TicketCategory;
  departmentId: UUID;
  departmentName: string;
  assigneeId: UUID | null;
  assigneeName: string | null;
  assignedAt?: string | null;
  createdById: UUID;
  createdByName: string;
  dueDate: string;
  sla: SLAInfo;
  tags: string[];
  attachmentCount: number;
  commentCount: number;
  
  // Triage-related fields
  submittedAt?: string;
  triagedAt?: string | null;
  rejectionReason?: string | null;
  pendingReason?: string | null;
  
  // Help request fields
  helpRequestDescription?: string | null; // Description of what help is needed
  helpRequestedAt?: string | null; // When help was requested
  helpers?: TicketHelper[];       // List of assigned helpers
  activities?: TicketActivityItem[]; // Activity timeline (from BFF detail response)
}

export interface TicketHelper {
  id: UUID;
  userId: UUID;
  userName: string;
  assignedAt: string;
  assignedById: UUID; // Manager who assigned this helper
  assignedByName: string;
}

/** Minimal activity record embedded in the ticket detail response. */
export interface TicketActivityItem {
  id:          UUID;
  type:        string;  // matches ActivityType enum values (snake_case)
  actor:       string;  // actorName from BFF
  description: string;
  timestamp:   string;  // createdAt ISO string from BFF
  fromStatus?: string | null;
  toStatus?:   string | null;
}

export enum TicketPriority {
  Emergency = 'emergency',
  High = 'high',
  Medium = 'medium',
  Low = 'low',
}

export enum TicketStatus {
  New = 'new', // Keep for backwards compatibility
  Submitted = 'submitted', // Initial state when user submits ticket
  Pending = 'pending', // Waiting for more information from user
  Triaged = 'triaged', // Approved by manager
  Rejected = 'rejected', // Rejected by manager
  Assigned = 'assigned', // Assigned to staff
  InProgress = 'in_progress',
  HelpRequested = 'help_requested', // Staff requested help
  SupportAssigned = 'support_assigned', // Helper assigned
  Blocked = 'blocked', // Ticket is blocked
  Resolved = 'resolved',
  Approved = 'approved', // Resolution approved
  Reopened = 'reopened', // Reopened after resolved
  Closed = 'closed',
}

export enum TicketCategory {
  Technical = 'technical',
  Administrative = 'administrative',
  Clinical = 'clinical',
  Other = 'other',
}

export interface SLAInfo {
  targetDate: string;
  remainingMinutes: number;
  percentage: number; // 0-100
  status: SLAStatus;
  breached: boolean;
}

export enum SLAStatus {
  Safe = 'safe',       // > 25%
  Warning = 'warning', // 10-25%
  Danger = 'danger',   // < 10%
  Breached = 'breached',
}

export interface TicketFilters {
  scope?: 'my' | 'all' | 'team';
  priority?: TicketPriority;
  status?: TicketStatus;
  departmentId?: UUID;
  assigneeId?: UUID;
  slaStatus?: SLAStatus;
  search?: string;
}

// Alias for backwards compatibility
export type TicketFilter = TicketFilters;
