/**
 * SignalRService — singleton wrapper around @microsoft/signalr HubConnection.
 *
 * Usage:
 *   signalRService.start()   // call after login
 *   signalRService.stop()    // call on logout
 *   signalRService.invoke('JoinTicketRoom', ticketId)
 *   signalRService.on('NewComment', handler)
 *   signalRService.off('NewComment', handler)
 *
 * Key design decision: event subscriptions (`on`/`off`) are stored in a local
 * registry so they survive connection rebuilds.  When `start()` creates a new
 * HubConnection the pending handlers are replayed onto it *before* `.start()`
 * is called, guaranteeing that hooks which registered before the connection
 * existed (or after a stop/start cycle) still receive events.
 */

import {
  HubConnection,
  HubConnectionBuilder,
  HubConnectionState,
  LogLevel,
} from '@microsoft/signalr';

import { HubEventName, HubEventPayloadMap } from './types';

// The hub URL is derived from the API base URL configured via Vite env.
const HUB_URL = (() => {
  const base = (import.meta.env.VITE_API_URL as string | undefined) ?? '';
  return `${base.replace(/\/+$/, '')}/collaboration-hub`;
})();

type AnyHandler = (...args: unknown[]) => void;

class SignalRService {
  private _conn: HubConnection | null = null;
  private _startPromise: Promise<void> | null = null;
  private _reconnectedCallbacks = new Set<() => void>();

  /**
   * Deferred subscription registry.
   * Handlers registered via `on()` are kept here so they can be replayed onto
   * a new HubConnection when `start()` is called (or re-called after stop).
   */
  private _handlers = new Map<string, Set<AnyHandler>>();

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  /** Build a new connection and start it.  Safe to call multiple times. */
  async start(): Promise<void> {
    if (this._conn?.state === HubConnectionState.Connected) return;
    if (this._startPromise) return this._startPromise;

    this._conn = new HubConnectionBuilder()
      .withUrl(HUB_URL, {
        accessTokenFactory: () => localStorage.getItem('auth_token') ?? '',
      })
      .withAutomaticReconnect([0, 2000, 5000, 10000, 30000])
      .configureLogging(
        import.meta.env.DEV ? LogLevel.Information : LogLevel.Warning,
      )
      .build();

    // Replay all deferred subscriptions onto the fresh connection
    for (const [event, handlers] of this._handlers) {
      for (const handler of handlers) {
        this._conn.on(event, handler);
      }
    }

    this._conn.onreconnecting(() =>
      console.log('[SignalR] 🔄 Reconnecting…'),
    );
    this._conn.onreconnected(() => {
      console.log('[SignalR] ✅ Reconnected');
      // Fire reconnected callbacks (room re-join etc.)
      for (const cb of this._reconnectedCallbacks) {
        try { cb(); } catch { /* ignore */ }
      }
    });
    this._conn.onclose((err) => {
      console.log('[SignalR] ❌ Connection closed', err ? `— ${err.message}` : '');
      this._startPromise = null;
    });

    this._startPromise = this._conn
      .start()
      .then(() => console.log('[SignalR] ✅ Connected to', HUB_URL))
      .catch((err) => {
        this._startPromise = null;
        // React 18 StrictMode may abort negotiation during dev-mode cleanup — ignore silently.
        const isAborted =
          err?.name === 'AbortError' ||
          err?.message?.includes('aborted') ||
          err?.message?.includes('stop() was called');
        if (isAborted) {
          console.debug('[SignalR] Start aborted (StrictMode cleanup). Will reconnect.');
          return;
        }
        // 404 means the hub endpoint is not deployed yet — log quietly and stop.
        const is404 =
          err?.message?.includes('404') ||
          err?.message?.includes('Not Found');
        if (is404) {
          console.debug('[SignalR] Hub not available (404). Real-time features disabled.');
          return; // do NOT throw — suppress cascade warnings
        }
        console.warn('[SignalR] Connection failed:', err);
        throw err;
      });

    return this._startPromise;
  }

  /** Gracefully close the hub connection. */
  async stop(): Promise<void> {
    if (!this._conn) return;
    // Do not interrupt an in-flight negotiation — the AbortError would cascade.
    // This can happen in React 18 StrictMode where cleanup fires before start() resolves.
    const state = this._conn.state;
    if (
      state === HubConnectionState.Connecting ||
      state === HubConnectionState.Reconnecting
    ) {
      console.debug('[SignalR] stop() skipped — connection still negotiating.');
      return;
    }
    await this._conn.stop();
    this._conn = null;
    this._startPromise = null;
    // NOTE: _handlers registry is preserved so a subsequent start() replays them.
  }

  // ── Group join / leave ────────────────────────────────────────────────────
  /**
   * Wait until the hub is in Connected state.
   * - Already connected  → resolves immediately.
   * - Still negotiating   → awaits the pending start() promise.
   * - Reconnecting        → waits for the next onreconnected callback.
   * - Disconnected        → calls start() first, then waits.
   * Times out after `timeoutMs` ms (default 30 s).
   */
  async whenConnected(timeoutMs = 30_000): Promise<void> {
    if (this.isConnected) return;

    // If a start is already in flight, wait for it
    if (this._startPromise) {
      await this._startPromise.catch(() => {});
      if (this.isConnected) return;
    } else {
      // No connection at all — kick off start()
      await this.start().catch(() => {});
      if (this.isConnected) return;
    }

    // Still not connected (e.g. reconnecting after a drop) — wait for reconnect
    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => {
        unsub();
        reject(new Error('[SignalR] Timed out waiting for connection'));
      }, timeoutMs);

      const unsub = this.onReconnected(() => {
        clearTimeout(timer);
        resolve();
      });
    });
  }

  /**
   * Register a callback that fires every time SignalR successfully reconnects.
   * Returns an unsubscribe function — call it in your useEffect cleanup.
   */
  onReconnected(callback: () => void): () => void {
    this._reconnectedCallbacks.add(callback);
    return () => this._reconnectedCallbacks.delete(callback);
  }
  /** Call a hub method (fire-and-forget with retry on disconnect). */
  async invoke(method: string, ...args: unknown[]): Promise<void> {
    if (!this._conn) return;
    if (this._conn.state !== HubConnectionState.Connected) return;
    try {
      await this._conn.invoke(method, ...args);
    } catch (err) {
      console.warn(`[SignalR] invoke('${method}') failed:`, err);
    }
  }

  // ── Event subscriptions ───────────────────────────────────────────────────

  /**
   * Subscribe to a hub event.  Works even before the connection is built —
   * the handler is stored in a deferred registry and replayed on the next
   * `start()` call.
   */
  on<E extends HubEventName>(
    event: E,
    handler: (payload: HubEventPayloadMap[E]) => void,
  ): void {
    const h = handler as AnyHandler;
    // Always store in registry (survives stop/start cycles)
    let set = this._handlers.get(event);
    if (!set) { set = new Set(); this._handlers.set(event, set); }
    set.add(h);
    // If connection already exists, attach immediately as well
    this._conn?.on(event, h);
  }

  off<E extends HubEventName>(
    event: E,
    handler: (payload: HubEventPayloadMap[E]) => void,
  ): void {
    const h = handler as AnyHandler;
    this._handlers.get(event)?.delete(h);
    this._conn?.off(event, h);
  }

  get isConnected(): boolean {
    return this._conn?.state === HubConnectionState.Connected;
  }
}

/** Application-wide singleton. */
export const signalRService = new SignalRService();
