import React from 'react';
import { TicketStatus } from '../../../models/Ticket';
import { getStatusLabel } from '../../../utils/ticketUtils';
import styles from './StatusBadge.module.css';

export interface StatusBadgeProps {
  status: TicketStatus | string;
  compact?: boolean;
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({ status, compact = false }) => {
  const statusStr = typeof status === 'string' ? status : String(status);
  const statusKey = statusStr.toLowerCase().replace(/_/g, '-');
  const label = getStatusLabel(status);
  
  return (
    <span className={`${styles.badge} ${styles[statusKey] || styles.default} ${compact ? styles.compact : ''}`}>
      <span className={styles.dot}></span>
      <span className={styles.label}>{label}</span>
    </span>
  );
};
