import React, { useState, useRef, useEffect, useCallback } from 'react';
import { UUID } from '../../../models/common';
import { Button } from '../../common/Button';
import { TabSlideout } from '../TabSlideout';
import { useAppToast } from '../../../hooks/useAppToast';
import styles from './ChatTab.module.css';

export interface ChatMessage {
  id: UUID;
  entityId: UUID; // Can be ticketId or taskId
  userId: string;
  userName: string;
  userAvatar?: string;
  message: string;
  timestamp: string;
}

export interface ChatTabProps {
  entityId: UUID;
  entityType: 'ticket' | 'task';
  messages?: ChatMessage[];
  onSendMessage?: (message: string) => Promise<void>;
  onDeleteMessage?: (messageId: UUID) => Promise<void>;
  currentUserId?: string; // Current logged-in user ID to align messages
  hasMore?: boolean;
  loading?: boolean;
  onLoadMore?: () => Promise<void>;
  /** True when the user has muted NEW_MESSAGE notifications for this entity. */
  isMuted?: boolean;
  /** Toggle mute state (optimistic). Shown as a bell button in the toolbar. */
  onToggleMute?: () => Promise<void>;
  /** True while fetching or toggling the mute preference. */
  muteLoading?: boolean;
}

export const ChatTab: React.FC<ChatTabProps> = ({
  entityId: _entityId,
  entityType,
  messages = [],
  onSendMessage,
  onDeleteMessage: _onDeleteMessage,
  currentUserId = '', // Provided by parent from auth context
  hasMore = false,
  loading = false,
  onLoadMore,
  isMuted,
  onToggleMute,
  muteLoading = false,
}) => {
  const [message, setMessage] = useState('');
  const [sending, setSending] = useState(false);
  const toast = useAppToast();
  const messagesRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  // Track whether user has scrolled up (to avoid forcing scroll-to-bottom while reading history)
  const isAtBottomRef = useRef(true);
  const touchStartYRef = useRef(0);
  // Dedicated load-more state (separate from parent `loading` which covers initial load)
  const [loadingMore, setLoadingMore] = useState(false);
  const loadingMoreRef = useRef(false); // sync guard — prevents double-calls in async handlers
  // Scroll-triggered reveal: messages start hidden; IntersectionObserver reveals each one
  // as it enters the scroll container + 120px lookahead (= "next item" pre-reveal).
  const revealedIdsRef = useRef(new Set<string>());
  const [revealedIds, setRevealedIds] = useState(new Set<string>());

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    const el = messagesRef.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior });
  };

  // Load-more helper: manages spinner state + restores scroll position after prepend
  const doLoadMore = useCallback(async (prevHeight: number) => {
    if (!onLoadMore || loadingMoreRef.current) return;
    loadingMoreRef.current = true;
    setLoadingMore(true);
    try {
      await onLoadMore();
    } finally {
      loadingMoreRef.current = false;
      setLoadingMore(false);
      requestAnimationFrame(() => {
        if (messagesRef.current) {
          messagesRef.current.scrollTop = messagesRef.current.scrollHeight - prevHeight;
        }
      });
    }
  }, [onLoadMore]);

  useEffect(() => {
    const el = messagesRef.current;
    if (!el) return;

    const onScroll = async () => {
      isAtBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
      if (el.scrollTop === 0 && hasMore && !loadingMoreRef.current && !loading) {
        await doLoadMore(el.scrollHeight);
      }
    };

    const onTouchStart = (e: TouchEvent) => {
      touchStartYRef.current = e.touches[0].clientY;
    };

    const onTouchEnd = async (e: TouchEvent) => {
      const deltaY = e.changedTouches[0].clientY - touchStartYRef.current;
      if (deltaY > 50 && el.scrollTop === 0 && hasMore && !loadingMoreRef.current && !loading) {
        await doLoadMore(el.scrollHeight);
      }
    };

    el.addEventListener('scroll', onScroll);
    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('touchend', onTouchEnd, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('touchend', onTouchEnd);
    };
  }, [hasMore, loading, doLoadMore]);

  // Auto-scroll to bottom when new messages arrive (only if already near bottom)
  useEffect(() => {
    if (isAtBottomRef.current) {
      scrollToBottom();
    }
  }, [messages]);

  // Scroll to bottom on initial load
  useEffect(() => {
    scrollToBottom('instant' as ScrollBehavior);
  }, []);

  // IntersectionObserver: re-runs whenever messages change (new load or loadMore).
  // Creates one observer per render cycle; reveals items that scroll into the
  // container + 120px lookahead margin so the very next hidden item is pre-revealed
  // before the user physically reaches it.
  useEffect(() => {
    const container = messagesRef.current;
    if (!container) return;

    const observer = new IntersectionObserver(
      (entries) => {
        const newIds: string[] = [];
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const id = (entry.target as HTMLElement).dataset.msgId;
            if (id && !revealedIdsRef.current.has(id)) {
              newIds.push(id);
              revealedIdsRef.current.add(id);
            }
            observer.unobserve(entry.target);
          }
        });
        if (newIds.length > 0) setRevealedIds(new Set(revealedIdsRef.current));
      },
      { root: container, rootMargin: '120px 0px 0px 0px', threshold: 0 },
    );

    container.querySelectorAll<HTMLElement>('[data-msg-id]').forEach((el) => {
      if (!revealedIdsRef.current.has(el.dataset.msgId!)) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim()) return;

    setSending(true);
    try {
      if (onSendMessage) {
        await onSendMessage(message.trim());
      }
      setMessage('');
      // Auto-focus input after sending
      setTimeout(() => inputRef.current?.focus(), 0);
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể gửi tin nhắn, vui lòng thử lại');
    } finally {
      setSending(false);
    }
  };

  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('vi-VN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getAvatarColor = (userId: string) => {
    const colors = [
      'var(--blue-500)',
      'var(--green-500)',
      'var(--purple-500)',
      'var(--orange-500)',
      'var(--pink-500)',
      'var(--teal-500)',
    ];
    const hash = userId.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return colors[hash % colors.length];
  };

  const getInitials = (name: string) => {
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return parts[0][0] + parts[parts.length - 1][0];
    }
    return name.substring(0, 2);
  };

  const entityLabel = entityType === 'ticket' ? 'phiếu' : 'task';

  const isOwnMessage = (msg: ChatMessage) => {
    return msg.userId === currentUserId;
  };

  const footerContent = (
    <div className={styles.footer}>
      <div className={styles.hint}>
        <i className="fas fa-info-circle"></i>
        <span>Sử dụng @tên để mention thành viên khác</span>
      </div>
      <form onSubmit={handleSubmit} className={styles.form}>
        <input
          ref={inputRef}
          type="text"
          className={styles.input}
          placeholder="Nhập tin nhắn nhanh..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          disabled={sending}
        />
        <Button type="submit" disabled={!message.trim() || sending} size="md">
          {sending ? (
            <>
              <i className="fas fa-spinner fa-spin"></i> 
              <span className={styles.submitText}>Đang gửi...</span>
            </>
          ) : (
            <>
              <i className="fas fa-paper-plane"></i> 
              <span className={styles.submitText}>Gửi</span>
            </>
          )}
        </Button>
      </form>
    </div>
  );

  const muteButton = onToggleMute !== undefined ? (
    <button
      className={`${styles.muteBtn} ${isMuted ? styles.muteBtnMuted : ''}`}
      onClick={onToggleMute}
      disabled={muteLoading}
      title={isMuted ? 'Bật thông báo tin nhắn' : 'Tắt thông báo tin nhắn'}
    >
      {muteLoading
        ? <i className="fas fa-spinner fa-spin" />
        : isMuted
          ? <i className="fas fa-bell-slash" />
          : <i className="fas fa-bell" />
      }
      <span>{isMuted ? 'Không theo dõi' : 'Theo dõi'}</span>
    </button>
  ) : undefined;

  return (
    <TabSlideout footer={footerContent} className={styles.chatTab} tabContentMaxHeight='500px' headerLeft={muteButton}>
      <div className={styles.messages} ref={messagesRef}>
        {(loadingMore || (hasMore && !loading)) && (
          <div className={styles.loadingMore}>
            {loadingMore ? (
              <>
                <span className={styles.dotsSpinner}>
                  <span className={styles.dot} />
                  <span className={styles.dot} />
                  <span className={styles.dot} />
                </span>
                <span>Đang tải thêm...</span>
              </>
            ) : (
              <>
                <i className="fas fa-arrow-up" />
                {' '}
                <span>Cuộn lên hoặc vuốt xuống để tải thêm</span>
              </>
            )}
          </div>
        )}
        {messages.length === 0 ? (
          <div className={styles.empty}>
            <i className="fas fa-comments"></i>
            <p>Chưa có tin nhắn nào</p>
            <span>Bắt đầu trao đổi về {entityLabel} này</span>
          </div>
        ) : (
          messages.map((msg) => {
            const isOwn = isOwnMessage(msg);
            return (
              <div
                key={msg.id}
                data-msg-id={msg.id}
                className={`${styles.message} ${isOwn ? styles.messageOwn : styles.messageOther}${revealedIds.has(msg.id) ? ` ${styles.revealed}` : ''}`}
              >
                {!isOwn && (
                  <div
                    className={styles.avatar}
                    style={{ backgroundColor: getAvatarColor(msg.userId) }}
                  >
                    {msg.userAvatar || getInitials(msg.userName)}
                  </div>
                )}
                <div className={styles.messageContent}>
                  {!isOwn && (
                    <div className={styles.messageHeader}>
                      <span className={styles.userName}>{msg.userName}</span>
                      <span className={styles.timestamp}>{formatTime(msg.timestamp)}</span>
                    </div>
                  )}
                  <div className={styles.messageBody}>
                    {msg.message}
                    {isOwn && (
                      <span className={styles.ownTimestamp}>{formatTime(msg.timestamp)}</span>
                    )}
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </TabSlideout>
  );
};
