import React from 'react';
import { PerformanceStats } from '../../../models/Statistics';
import { StatsCard, StatsCardsGrid } from '../../common';

interface PerformanceCardsProps {
  data: PerformanceStats;
}

export const PerformanceCards: React.FC<PerformanceCardsProps> = ({ data }) => {
  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tổng công việc"
        value={data.totalTasks}
        icon="fas fa-tasks"
        variant="total"
      />
      <StatsCard
        label="Đã hoàn thành"
        value={data.completedTasks}
        icon="fas fa-check-circle"
        variant="success"
      />
      <StatsCard
        label="Tỷ lệ hoàn thành"
        value={`${data.completionRate}%`}
        icon="fas fa-chart-pie"
        variant="primary"
      />
      <StatsCard
        label="Tổng thời gian"
        value={`${data.totalTime}h`}
        icon="fas fa-clock"
        variant="warning"
      />
      <StatsCard
        label="Đánh giá TB"
        value={data.averageRating.toFixed(1)}
        icon="fas fa-star"
        variant="info"
      />
      <StatsCard
        label="Vi phạm SLA"
        value={data.slaViolations}
        icon="fas fa-exclamation-triangle"
        variant="danger"
      />
      {/* <StatsCard
        label="Hạng"
        value={`#${data.rank}`}
        icon="fas fa-trophy"
        variant="primary"
      /> */}
    </StatsCardsGrid>
  );
};
