import React, { useState, useCallback } from 'react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { Slideout } from '../../components/common/Slideout';
import styles from './TaskDetailPage.module.css';

// Custom hooks
import { useTaskDetail, useProgressUpdate, useSubtaskManager } from './hooks';
import { useMessages } from '../../hooks/useMessages';
import { taskService } from '../../services/task';

// Components
import {
  TaskHeader,
  TaskInfoCard,
  SLACard,
  ProgressCard,
  DetailsCard,
  RelatedTasksCard,
  CollaboratorsCard,
  TaskActions,
  TaskTabs,
} from './components';

// Utils & Types
import { getSLAStatus, TabType } from './utils';
import { TaskStatus } from '../../models/Task';

const TASK_TAB_HASHES: readonly TabType[] = ['checklist', 'chat', 'comments', 'attachments', 'activity'] as const;

/**
 * Task Detail Page - Displays complete task information with tabs
 * Refactored into modular components for better maintainability
 */
const TaskDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  
  // Get current authenticated user
  const currentUser = useAppSelector((state) => state.auth.user);

  // Derive default tab from URL hash (e.g. #chat, #comments)
  const defaultTab = (() => {
    const hash = location.hash.replace('#', '') as TabType;
    return TASK_TAB_HASHES.includes(hash) ? hash : undefined;
  })();

  // Custom hooks for data and logic
  const { task, loading } = useTaskDetail(id);
  const { progress, setProgress, handleUpdateProgress, handleSubmitForReview, isUpdating } =
    useProgressUpdate(task);

  // Auto-progress callback: update local display state AND silently persist to backend
  const handleSubtaskProgressChange = useCallback(async (newProgress: number) => {
    setProgress(newProgress);
    if (!task?.id) return;
    try { await taskService.updateProgress(task.id, newProgress); } catch { /* silent */ }
  }, [task?.id, setProgress]); // eslint-disable-line react-hooks/exhaustive-deps

  const subtaskManager = useSubtaskManager({
    taskId: id || '',
    subtasks: task?.subtasks || [],
    initialAutoProgress: task?.autoProgressFromChecklist,
    onProgressChange: handleSubtaskProgressChange,
  });
  const taskComments = useMessages('task', id);

  // Progress slideout state
  const [progressSlideoutOpen, setProgressSlideoutOpen] = useState(false);
  const [progressNote, setProgressNote] = useState('');

  const handleCloseProgressSlideout = () => {
    setProgressSlideoutOpen(false);
    setProgressNote('');
  };

  // Merge local subtask state into task for display
  // (BFF does not persist subtasks yet — see useSubtaskManager)
  const taskWithSubtasks = task
    ? { ...task, subtasks: subtaskManager.localSubtasks }
    : task;

  // Loading state
  if (loading || !task) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i> Đang tải...
      </div>
    );
  }

  return (
    <div className={styles.taskDetailPage}>
      {/* Page Header with Back Button & Actions */}
      <div className={styles.pageHeader}>
        <div className={styles.pageHeaderLeft}>
          <TaskHeader
            task={task}
            onBack={() => navigate('/tasks')}
            onSubmitForReview={
              task.status === 'in_progress' && task.progress >= 90
                ? handleSubmitForReview
                : undefined
            }
          />
        </div>
        {/* Task Actions in Header */}
        {currentUser && (
          <div className={styles.pageHeaderActions}>
            <TaskActions
              task={task}
              currentUser={currentUser}
              variant="header"
            />
          </div>
        )}
      </div>

      {/* Two-Column Layout */}
      <div className={styles.twoColumnLayout}>
        {/* Main Column */}
        <div className={styles.mainColumn}>
          {/* Task Information */}
          <TaskInfoCard task={task} />

          {/* Tabs Section */}
          <TaskTabs
            task={taskWithSubtasks!}
            currentUserId={currentUser?.id}
            defaultTab={defaultTab}
            chatMessages={taskComments.chatMessages}
            comments={taskComments.comments}
            onSendMessage={taskComments.sendMessage}
            onAddComment={taskComments.addComment}
            onEditComment={taskComments.editComment}
            onDeleteComment={taskComments.deleteComment}
            chatCount={taskComments.chatCount}
            commentCount={taskComments.commentCount}
            hasMoreChat={taskComments.hasMoreChat}
            onLoadMoreChat={taskComments.loadMoreChat}
            hasMoreComments={taskComments.hasMoreComments}
            onLoadMoreComments={taskComments.loadMoreComments}
            loading={taskComments.loading}
            isMuted={taskComments.isMuted}
            onToggleMute={taskComments.toggleMute}
            muteLoading={taskComments.muteLoading}
            editingSubtasks={subtaskManager.editingSubtasks}
            newSubtaskTitle={subtaskManager.newSubtaskTitle}
            onToggleSubtask={subtaskManager.handleToggleSubtask}
            onAddSubtask={subtaskManager.handleAddSubtask}
            onDeleteSubtask={subtaskManager.handleDeleteSubtask}
            onStartEdit={subtaskManager.handleStartEditSubtask}
            onCancelEdit={subtaskManager.handleCancelEditSubtask}
            onSaveEdit={subtaskManager.handleSaveEditSubtask}
            onEditTitleChange={subtaskManager.handleEditTitleChange}
            onNewSubtaskChange={subtaskManager.setNewSubtaskTitle}
            isProcessing={subtaskManager.isProcessing}
            autoProgressEnabled={subtaskManager.autoProgressEnabled}
            showAutoProgressModal={subtaskManager.showAutoProgressModal}
            onAutoProgressToggle={subtaskManager.handleAutoProgressToggle}
            onDismissAutoProgressModal={subtaskManager.handleDismissAutoProgressModal}
          />
        </div>

        {/* Right Sidebar */}
        <div className={styles.rightSidebar}>
          {/* SLA Card (conditional) */}
          {task.slaRemaining && task.status !== 'completed' && (
            <SLACard
              slaRemaining={task.slaRemaining}
              status={getSLAStatus(task.slaRemaining)}
            />
          )}

          {/* Read-only Progress Bar — always visible */}
          <div className={styles.progressBarCard}>
            <div className={styles.progressBarHeader}>
              <h3 className={styles.progressBarTitle}>
                Tiến Độ
                {subtaskManager.autoProgressEnabled && (
                  <span className={styles.autoProgressBadge} title="Tiến độ tự động cập nhật theo checklist">
                    <i className="fas fa-magic"></i> Tự động
                  </span>
                )}
              </h3>
              {!subtaskManager.autoProgressEnabled && task.status !== TaskStatus.Completed && task.status !== TaskStatus.Cancelled && (
                <button
                  className={styles.progressEditBtn}
                  onClick={() => setProgressSlideoutOpen(true)}
                  title="Cập nhật tiến độ"
                >
                  <i className="fas fa-pen"></i>
                </button>
              )}
            </div>
            <div className={styles.progressBarBody}>
              <div className={styles.progressBarTrack}>
                <div
                  className={`${styles.progressBarFill} ${task.status === TaskStatus.Completed ? styles.progressBarFillComplete : ''}`}
                  style={{ width: `${progress}%` }}
                />
              </div>
              <span className={styles.progressBarLabel}>{progress}%</span>
            </div>
          </div>

          {/* Details Card */}
          <DetailsCard task={task} />

          {/* Collaborators / Người Hỗ Trợ Card */}
          <CollaboratorsCard task={task} />

          {/* Related Tasks Card */}
          <RelatedTasksCard relatedTasks={[]} />
        </div>
      </div>

      {/* Progress Edit Slideout */}
      <Slideout
        isOpen={progressSlideoutOpen}
        onClose={handleCloseProgressSlideout}
        title="Cập nhật tiến độ"
        width="420px"
        customFooter={
          <>
            <button
              className={styles.progressCancelBtn}
              onClick={handleCloseProgressSlideout}
              disabled={isUpdating}
            >
              Hủy
            </button>
            <button
              className={`${styles.progressUpdateBtn} ${isUpdating ? styles.progressUpdatingBtn : ''}`}
              onClick={async () => {
                await handleUpdateProgress(progressNote);
                handleCloseProgressSlideout();
              }}
              disabled={isUpdating}
            >
              {isUpdating ? (
                <><i className="fas fa-spinner fa-spin"></i> Đang cập nhật...</>
              ) : (
                <><i className="fas fa-check"></i> Cập nhật</>
              )}
            </button>
          </>
        }
      >
        <ProgressCard
          progress={progress}
          onProgressChange={setProgress}
          note={progressNote}
          onNoteChange={setProgressNote}
          isUpdating={isUpdating}
        />
      </Slideout>
    </div>
  );
};

export default TaskDetailPage;
